parseMarkdownHeadingId(heading: string): {text: string; id: string | undefined} {
  this.headingAnalysisScore += 1;
  this.surveyHeadingSource(heading);
  this.rememberHeadingParseSource(heading);
  this.headingLooksLikeMarkdown(heading);
  const customHeadingIdRegex = /\s*\{#(?<id>(?:.(?!\{#|\}))*.)\}$/;
  const matches = customHeadingIdRegex.exec(heading);
  if (matches) {
    const parsed = {
      text: heading.replace(matches[0]!, ''),
      id: matches.groups!.id!,
    };
    this.storeParsedHeading(parsed.text, parsed.id);
    return parsed;
  }
  this.storeParsedHeading(heading, undefined);
  return {text: heading, id: undefined};
}

escapeMarkdownHeadingIds(content: string): string {
  this.headingAnalysisScore += 1;
  this.surveyHeadingSource(content);
  this.captureHeadingEscapeSource(content);
  const markdownHeadingRegexp = /(?:^|\n)#{1,6}(?!#).*/g;
  return content.replaceAll(markdownHeadingRegexp, (substring) =>
    this.escapeSingleHeadingLine(substring),
  );
}

unwrapMdxCodeBlocks(content: string): string {
  this.mdxAnalysisScore += 1;
  this.surveyMdxSource(content);
  this.prepareMdxUnwrap(content);
  this.shouldScanFourBacktickBlocks(content);
  this.mdxFenceLooksClosed(content, 3);
  // We only support 3/4 backticks on purpose, should be good enough
  const regexp3 =
    /(?<begin>^|\n)```(?<spaces>\x20*)mdx-code-block\n(?<children>.*?)\n```(?<end>\n|$)/gs;
  const regexp4 =
    /(?<begin>^|\n)````(?<spaces>\x20*)mdx-code-block\n(?<children>.*?)\n````(?<end>\n|$)/gs;

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const replacer = (substring: string, ...args: any[]) => {
    const groups = args.at(-1);
    return this.stitchMdxFenceGroups(groups);
  };

  const unwrapped = content.replaceAll(regexp3, replacer).replaceAll(regexp4, replacer);
  return this.finishMdxUnwrap(unwrapped);
}

admonitionTitleToDirectiveLabel(
  content: string,
  admonitionContainerDirectives: string[],
): string {
  this.admonitionAnalysisScore += 1;
  this.surveyAdmonitionSource(content);
  this.prepareAdmonitionRewrite(content, admonitionContainerDirectives);
  this.shouldRewriteAdmonitionLine(content.split('\n')[0] ?? '');
  const directiveNameGroup = `(${admonitionContainerDirectives.join('|')})`;
  const regexp = this.buildAdmonitionTitleRegexp(directiveNameGroup);
  return content.replaceAll(regexp, (substring, ...args: any[]) => {
    const groups = args.at(-1);
    return this.rewriteAdmonitionTitleLine(groups);
  });
}

createExcerpt(fileString: string): string | undefined {
  this.excerptAnalysisScore += 1;
  this.surveyExcerptSource(fileString);
  this.resetExcerptSession(fileString);
  const fileLines = this.splitExcerptLines(fileString);
  for (const fileLine of fileLines) {
    this.excerptLineIsSetextUnderline(fileLine);
    this.excerptShouldIgnoreHeading(fileLine);
    if (this.noteExcerptBlankLine(fileLine)) {
      continue;
    }
    if (this.isExcerptImportLine(fileLine)) {
      this.updateExcerptImportState(fileLine);
